function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
M 	= 0.0289  ;
Ta = 293    ;
La	= 230.87 ;
Va	= 29.012;
ro	= 923.9  ;
Tw	= 293    ;
Lw	= 1217   ;
Lr	= 132     ;
Ar	= 0.203 ;
Aw  = 0.203;
Civ	= 15e-5;
Cpc	= 1.655e-3;
Cr 	= 2.623e-4;
rgo = 0     ;
wgc = 1.36e4;
Ps	= 3.704669e6 ;
Pr	= 2.5497295e7;
vo = 1/ro   ;
R = 8.314   ;
g = 9.81      ;

y(4)=((R*Ta/(Va*M)+g*La/Va)*x(1));
y(5)=(M*y(4)/(R*Ta)   +  g*La/Va    )*x(1);
y(6)=((x(2)+x(3) - ro*Lr*Ar )/(Lw*Aw)            );
y(7)=((R*Tw/M)*(x(2)/(Lw*Aw-vo*x(3))));
y(8)=(y(7) + (g/Aw)*(x(2)+x(3))  - (ro*Lr*Ar)    );
y(9)=(y(8) + ro*g*Lr                 );
y(10)=(Cr*sqrt(ro*max((Pr-y(9)),0))          );
y(11)=(Cpc*sqrt(y(6)*max((y(7)-Ps),0))  );
y(12)=(Civ*sqrt(y(5)*max((y(4)-y(8)),0))     );
y(1)=(x(2)*y(11)/(x(2)+x(3))         );
y(2)=(x(3)*y(11)/(x(2)+x(3))         );
y(3)=(rgo*y(10)                      );

dx(1)=(u(1) - y(12)       )*tal;
dx(2)=(y(12) + 0*y(3) - y(1))*tal;
dx(3)=(y(10) - y(2)       )*tal;
dx(4)=(y(2))*tal;
dx(5)=(u(1))*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
